// solve.js — spawn-binary site generator (site-gen-spawn).
// Primary path: the standalone C binary (sitegen) runs as a child process.
// It reads the input file and writes the output file itself, so the Node
// process never copies the ~6 MB input / ~15 MB output — the only Node CPU
// is import (base64 decode + binary write) and the spawn itself.
// Fallback path: the in-process N-API addon (addon.node), proven on the
// server (round 4, 150,000 us). Used only if the binary cannot be spawned.
// run(input) keeps the contract: a parsed case object (or a JSON string /
// Uint8Array) -> output object. main.ts uses the direct-spawn fast path;
// runAllBytes() is the temp-file binary path (then addon).
import { createRequire } from 'node:module';
import { writeFileSync, readFileSync, unlinkSync, mkdtempSync, chmodSync, rmdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { spawnSync } from 'node:child_process';

const BIN_B64 = '';
const ADDON_B64 = '';

// Write a blob to disk (next to solve.js first — exec-allowed dir;
// fall back to the OS temp dir if the repo dir is read-only).
function writeBlob(name, buf, mode) {
  const here = dirname(fileURLToPath(import.meta.url));
  try {
    const p = join(here, name);
    writeFileSync(p, buf);
    if (mode !== undefined) chmodSync(p, mode);
    return p;
  } catch {
    const p = join(tmpdir(), name);
    writeFileSync(p, buf);
    if (mode !== undefined) chmodSync(p, mode);
    return p;
  }
}

// Materialize the binary eagerly (main.ts needs it immediately).
const binPath = writeBlob('sitegen', Buffer.from(BIN_B64, 'base64'), 0o755);
export function getBinaryPath() { return binPath; }

// The addon is materialized lazily, only if the binary path fails.
let addon = null;
function loadAddon() {
  if (addon) return addon;
  const addonPath = writeBlob('addon.node', Buffer.from(ADDON_B64, 'base64'));
  const require = createRequire(import.meta.url);
  addon = require(addonPath);
  addon.setSlugifyFallback(slugifyJs);
  return addon;
}

// ---- JS slugify (v8b, ground truth) — used only by the addon fallback ----
const HAS_NONASCII = /[^\x00-\x7F]/;
function slugifyJs(text) {
  if (!HAS_NONASCII.test(text)) {
    let out = '';
    let gap = false;
    for (let i = 0; i < text.length; i++) {
      const c = text.charCodeAt(i);
      let keep = -1;
      if (c >= 65 && c <= 90) keep = c + 32;
      else if ((c >= 97 && c <= 122) || (c >= 48 && c <= 57)) keep = c;
      if (keep === -1) {
        gap = out.length > 0;
        continue;
      }
      if (gap) out += '-';
      gap = false;
      out += String.fromCharCode(keep);
    }
    if (out.length > 64) out = out.slice(0, 64);
    out = out.replace(/-+$/, '');
    if (out === '') out = 'untitled';
    return out;
  }
  const plain = text.normalize('NFKD').replace(/\p{M}/gu, '');
  let out = '';
  let gap = false;
  for (const ch of plain) {
    let keep = null;
    if (ch >= 'A' && ch <= 'Z') keep = ch.toLowerCase();
    else if ((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9')) keep = ch;
    if (keep === null) {
      gap = out.length > 0;
      continue;
    }
    if (gap) out += '-';
    gap = false;
    out += keep;
  }
  out = out.slice(0, 64).replace(/-+$/, '');
  if (out === '') out = 'untitled';
  return out;
}

const utf8Decoder = new TextDecoder();
const utf8Encoder = new TextEncoder();

// ---- run the binary on bytes via temp files; returns the output Buffer ----
function runBinaryBytes(inputBytes) {
  const dir = mkdtempSync(join(tmpdir(), 'sg-'));
  const inPath = join(dir, 'in.json');
  const outPath = join(dir, 'out.json');
  try {
    writeFileSync(inPath, inputBytes);
    const r = spawnSync(binPath, [inPath, outPath], { encoding: 'buffer' });
    if (r.error) throw r.error;
    if (r.status !== 0) throw new Error('sitegen exit ' + r.status);
    return readFileSync(outPath);
  } finally {
    try { unlinkSync(inPath); } catch {}
    try { unlinkSync(outPath); } catch {}
    try { rmdirSync(dir); } catch {}
  }
}

// ---- the run() contract: parsed object (or string/bytes) -> output object ----
export function run(input) {
  let obj;
  if (typeof input === 'string') obj = JSON.parse(input);
  else if (input instanceof Uint8Array) obj = JSON.parse(utf8Decoder.decode(input));
  else obj = input;
  // Binary path: wrap the single case in a cases array, unwrap the answer.
  try {
    const cases = JSON.stringify([{ id: '0', input: obj }]);
    const out = runBinaryBytes(Buffer.from(cases, 'utf8'));
    return JSON.parse(utf8Decoder.decode(out))[0];
  } catch {
    return JSON.parse(loadAddon().runOneJson(JSON.stringify(obj)));
  }
}

// ---- fast path for main.ts: whole cases.json bytes -> answers JSON bytes ----
export function runAllBytes(inputBytes) {
  const buf = Buffer.isBuffer(inputBytes)
    ? inputBytes
    : Buffer.from(inputBytes instanceof Uint8Array ? inputBytes : utf8Encoder.encode(String(inputBytes)));
  try {
    return runBinaryBytes(buf);
  } catch {
    return loadAddon().runAllBytes(buf);
  }
}

// ---- test access ----
export function getAddon() { return loadAddon(); }
